  const before=root.signature||'';
  const index=new Map();
  root.tree=await scanDirectory(root.handle,'',index);
  root.index=index;
  root.signature=treeSignature(root.tree);
  renderSide();
  return root.signature!==before;
}
async function refreshAllFsTrees(){
